mapper.select:
/* isry.itgcms.dyncBrd.mapper.DyncCmntBrdMapper.selectDynamicCmntBoardList 공통팀 유민상 */ WITH SUB_TEMP AS (SELECT A.NTABRD_ESNTAL_NO , A.BBSCTT_ESNTAL_NO
, '|'||LISTAGG (A.NTABRD_COL_ESNTAL_ID, '|') WITHIN GROUP (ORDER BY A.BBSCTT_ESNTAL_NO) AS NTABRD_COL_ESNTAL_ID_LIST , '|'||LISTAGG (A.NTABRD_COL_CN,'|') WITHIN GROUP (ORDER BY A.BBSCTT_ESNTAL_NO) AS NTABRD_COL_CN_LIST
/* , MAX(SYS_CONNECT_BY_PATH (A.NTABRD_COL_ESNTAL_ID, '|')) AS NTABRD_COL_ESNTAL_ID_LIST */ /* , MAX(SYS_CONNECT_BY_PATH (A.NTABRD_COL_CN,'|')) AS NTABRD_COL_CN_LIST */
FROM ( SELECT A.NTABRD_ESNTAL_NO , A.BBSCTT_ESNTAL_NO , A.NTABRD_COL_ESNTAL_ID , A.NTABRD_COL_CN , (ROW_NUMBER () OVER (PARTITION BY A.NTABRD_ESNTAL_NO ,A.BBSCTT_ESNTAL_NO ORDER BY A.NTABRD_ESNTAL_NO, A.BBSCTT_ESNTAL_NO, A.NTABRD_COL_ESNTAL_ID )) RNUM FROM SBA120 A WHERE 1=1 AND NTABRD_ESNTAL_NO = #{NTABRD_ESNTAL_NO} AND NVL(A.DEL_YN, 'N') != 'Y'
) A /* START WITH A.RNUM = 1 CONNECT BY PRIOR A.RNUM = (A.RNUM - 1) AND PRIOR A.NTABRD_ESNTAL_NO = A.NTABRD_ESNTAL_NO AND PRIOR A.BBSCTT_ESNTAL_NO = A.BBSCTT_ESNTAL_NO */ GROUP BY A.NTABRD_ESNTAL_NO, A.BBSCTT_ESNTAL_NO ), TEMP AS ( SELECT B.BBSCTT_ESNTAL_NO , B.NTABRD_ESNTAL_NO , B.BBSCTT_SN , B.BBSCTT_TTL_NM , B.BBSCTT_CN , FRST_REG_DT , B.RDCNT_NOCS , B.FRST_RGTR_ID , DEC_B64(SA_FN_GET_NAME(B.FRST_RGTR_ID)) AS FRST_RGTR_NM , B.ATFINO , (SELECT MAX(MNG_SN) FROM SAB821 WHERE ATFINO = B.ATFINO AND FILE_STTS_SE_CD != 'D' AND ATCMFL_CL_NM = '0') AS ATFI_CNT , B.RLS_YN , B.NTC_MATTER_YN , CASE WHEN TRUNC(SYSDATE - B.FRST_REG_DT) > 1 THEN 'N' ELSE 'Y' END AS NEW_BBSCTT , A.NTABRD_COL_ESNTAL_ID_LIST , A.NTABRD_COL_CN_LIST , (SELECT COUNT(*) FROM SBA111 C WHERE NVL(C.DEL_YN, 'N') != 'Y' AND C.NTABRD_ESNTAL_NO = B.NTABRD_ESNTAL_NO AND C.BBSCTT_ESNTAL_NO = B.BBSCTT_ESNTAL_NO ) AS CMNT_CNT FROM SUB_TEMP A, SBA110 B WHERE 1=1 AND B.NTABRD_ESNTAL_NO = #{NTABRD_ESNTAL_NO} AND A.BBSCTT_ESNTAL_NO(+) = B.BBSCTT_ESNTAL_NO AND A.NTABRD_ESNTAL_NO(+) = B.NTABRD_ESNTAL_NO AND NVL(B.DEL_YN, 'N') != 'Y' ORDER BY B.FRST_REG_DT DESC )
SELECT T.* , COUNT(DISTINCT BBSCTT_ESNTAL_NO) OVER() AS TOT_CNT , COUNT(*) OVER() AS REAL_TOT_CNT FROM ( SELECT A.* , 'Y' AS HIGH_LIGHT_YN FROM TEMP A WHERE NTC_MATTER_YN = 'Y'
UNION ALL
SELECT B.* , 'N' AS HIGH_LIGHT_YN FROM TEMP B ) T WHERE 1=1
AND (BBSCTT_TTL_NM LIKE '%' || #{SEARCH_DATA} || '%' OR BBSCTT_CN LIKE '%' || #{SEARCH_DATA} || '%')
AND BBSCTT_TTL_NM LIKE '%'|| #{SEARCH_DATA} || '%'
AND BBSCTT_CN LIKE '%' || #{SEARCH_DATA} || '%'
AND C##RG.SA_FN_GET_NAME(FRST_RGTR_ID) = #{SEARCH_DATA}
AND BBSCTT_SN = #{SEARCH_DATA}
AND TO_CHAR(FRST_REG_DT,'YYYYMMDD') BETWEEN #{START_DATE} AND #{END_DATE}
AND (REGEXP_SUBSTR(NTABRD_COL_CN_LIST , '[^|]+',2, DECODE(INSTR(NTABRD_COL_ESNTAL_ID_LIST, #{item.KEY})/2, 0, null, INSTR(NTABRD_COL_ESNTAL_ID_LIST, #{item.KEY})/2)) LIKE '%'|| #{item.VALUE} ||'%')
AND (REGEXP_SUBSTR(NTABRD_COL_CN_LIST , '[^|]+',2, DECODE(INSTR(NTABRD_COL_ESNTAL_ID_LIST, #{item.KEY})/2, 0, null, INSTR(NTABRD_COL_ESNTAL_ID_LIST, #{item.KEY})/2)) = #{item.VALUE})
ORDER BY HIGH_LIGHT_YN DESC, FRST_REG_DT DESC

mapper.insert:


                SELECT SBA111_SQ01.NEXTVAL AS CMNT_ESNTAL_NO
                  FROM DUAL



		/* isry.itgcms.dyncBrd.mapper.DyncCmntBrdMapper.insertDynamicCmntBoardCmntList 공통팀 유민상 */
		INSERT INTO SBA111(
			  BBSCTT_ESNTAL_NO
			, NTABRD_ESNTAL_NO
			, CMNT_ESNTAL_NO
			, CMNT_CN

                , ATFINO


                , UP_CMNT_ESNTAL_NO


                , CNTN_IP_ADDR

            , DEL_YN
			, FRST_RGTR_ID
			, FRST_REG_DT
			, LAST_MDFR_ID
			, LAST_MDFCN_DT
		)VALUES(
			  #{BBSCTT_ESNTAL_NO}
			, #{NTABRD_ESNTAL_NO}
			, #{CMNT_ESNTAL_NO}
			, #{CMNT_CN}

                , #{ATFINO}


                , #{UP_CMNT_ESNTAL_NO}


                , #{CNTN_IP_ADDR}

            , 'N'
			, #{FRST_RGTR_ID}
			, SYSDATE
			, #{LAST_MDFR_ID}
			, SYSDATE
		)

mapper.update:
/* isry.itgcms.dyncBrd.mapper.DyncCmntBrdMapper.updateDynamicCmntBoardCmntList 공통팀 유민상 */
UPDATE SBA111 SET
      CMNT_CN = #{CMNT_CN}
    , LAST_MDFCN_DT = SYSDATE
    , LAST_MDFR_ID = #{LAST_MDFR_ID}

WHERE 1=1
AND NTABRD_ESNTAL_NO = #{NTABRD_ESNTAL_NO__origin}
AND BBSCTT_ESNTAL_NO = #{BBSCTT_ESNTAL_NO__origin}
AND CMNT_ESNTAL_NO =   #{CMNT_ESNTAL_NO__origin}

/* isry.itgcms.dyncBrd.mapper.DyncCmntBrdMapper.deleteDynamicCmntBoardCmntList 공통팀 유민상 */
UPDATE SBA111 SET
      DEL_YN = 'Y'
    , LAST_MDFCN_DT = SYSDATE
    , LAST_MDFR_ID = #{LAST_MDFR_ID}
WHERE 1=1
AND NTABRD_ESNTAL_NO = #{NTABRD_ESNTAL_NO__origin}
AND BBSCTT_ESNTAL_NO = #{BBSCTT_ESNTAL_NO__origin}
AND CMNT_ESNTAL_NO =   #{CMNT_ESNTAL_NO__origin}
